Output8[Expected Approach] Using Sliding Window Technique - O(n) Time and O(1) SpaceThe idea is to use two pointers, start and end, to mark the start and end points of the current subarray (or window). Initially, both pointers are set at the beginning of the array. Continuously increase the size of the current window by incrementing the end pointer while keeping track of the count of zeros within the window.If at any point the count of zeros exceeds k, shrink the window by incrementing the start pointer until the count is reduced to k. The result will be the maximum length among all windows that contain at most k zeros.
            C++

    #include <iostream>
#include <vector>
using namespace std;

int maxOnes(vector<int> &arr, int k) {
    int res = 0;

    // Start and end pointer of the window 
    int start = 0, end = 0; 

    // Counter to keep track of zeros in current window
    int cnt = 0;

    while (end < arr.size()) {
        if (arr[end] == 0)
            cnt++;

        // Shrink the window from left if number of 
        // zeroes are greater than k
        while (cnt > k) {
            if (arr[start] == 0)
                cnt--;

            start++;
        }

        res = max(res, (end - start + 1));

        // Increment end pointer to expand the window
        end++; 
    }

    return res; 
}

int main() {
    vector<int> arr = {1, 0, 0, 1, 1, 0, 1, 0, 1, 1, 1}; 
    int k = 2;
    cout << maxOnes(arr, k);
    return 0;
}


